 				t.Fatalf("run(%d) returned error: %v", tt.n, err)
 			}
 			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -93,7 +94,7 @@ func TestRunJSON(t *testing.T) {
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, true); err != nil {
+			if err := run(&buf, tt.n, true, false); err != nil {
 				t.Fatalf("run(%d, json) returned error: %v", tt.n, err)
 			}
 			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -124,10 +125,11 @@ func TestRunRejectsInvalidCount(t *testing.T) {
 	for _, mode := range []struct {
 		name   string
 		asJSON bool
-	}{{"text", false}, {"json", true}} {
+		pretty bool
+	}{{"text", false, false}, {"json", true, false}, {"pretty text", false, true}} {
 		for _, n := range []int{0, -5} {
 			var buf bytes.Buffer
-			err := run(&buf, n, mode.asJSON)
+			err := run(&buf, n, mode.asJSON, mode.pretty)
 			if err == nil {
 				t.Fatalf("run(%d, %s) succeeded, want error", n, mode.name)
 			}
@@ -140,3 +142,70 @@ func TestRunRejectsInvalidCount(t *testing.T) {
 		}
 	}
 }
+
+// wantPrettyLines returns the expected -pretty text output for the first
+// n numbers: index and value each right-aligned to the width of the
+// largest index and value (the ones on the n-th line), separated by
+// ": ". Padding is built explicitly so the expected strings do not
+// depend on the implementation's formatting.
+func wantPrettyLines(n int) []string {
+	idxW := len(strconv.Itoa(n))
+	valW := len(Fib(n).String())
+	lines := make([]string, n)
+	for i := 1; i <= n; i++ {
+		idx := strconv.Itoa(i)
+		val := Fib(i).String()
+		lines[i-1] = strings.Repeat(" ", idxW-len(idx)) + idx + ": " +
+			strings.Repeat(" ", valW-len(val)) + val
+	}
+	return lines
+}
+
+func TestRunPretty(t *testing.T) {
+	tests := []struct {
+		name string
+		n    int
+	}{
+		{"pretty n=5 prints five padded lines", 5},
+		// The default pretty path still prints 100 numbers; the exact
+		// last line (and every line before it) is computed, not hardcoded.
+		{"pretty default prints 100 lines", defaultCount},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			var buf bytes.Buffer
+			if err := run(&buf, tt.n, false, true); err != nil {
+				t.Fatalf("run(%d, pretty) returned error: %v", tt.n, err)
+			}
+			got := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
+			want := wantPrettyLines(tt.n)
+			if len(got) != len(want) {
+				t.Fatalf("run(%d, pretty) printed %d lines, want %d", tt.n, len(got), len(want))
+			}
+			for i := range want {
+				if got[i] != want[i] {
+					t.Errorf("line %d = %q, want %q", i+1, got[i], want[i])
+				}
+			}
+		})
+	}
+}
+
+func TestRunPrettyJSONMatchesJSON(t *testing.T) {
+	var pretty, plain bytes.Buffer
+	if err := run(&pretty, 3, true, true); err != nil {
+		t.Fatalf("run(3, json, pretty) returned error: %v", err)
+	}
+	if err := run(&plain, 3, true, false); err != nil {
+		t.Fatalf("run(3, json) returned error: %v", err)
+	}
+	if pretty.String() != plain.String() {
+		t.Errorf("-pretty -json output %q differs from -json output %q", pretty.String(), plain.String())
+	}
+	lines := strings.Split(strings.TrimSuffix(pretty.String(), "\n"), "\n")
+	for i, line := range lines {
+		if want := wantJSONLine(i + 1); line != want {
+			t.Errorf("line %d = %q, want exactly %q", i+1, line, want)
+		}
+	}
+}
diff --git a/main.go b/main.go
index 435e69a..61355e1 100644
--- a/main.go
+++ b/main.go
@@ -1,7 +1,7 @@
 // Command gofib prints Fibonacci numbers, one per line, prefixed with
 // the index: "1: 1", "2: 1", "3: 2", ... By default it prints the first
-// 100; the -n flag changes how many are printed, and -json switches to
-// JSON Lines output.
+// 100; the -n flag changes how many are printed, -json switches to
+// JSON Lines output, and -pretty aligns text output in two columns.
 package main

 import (
@@ -11,6 +11,7 @@ import (
 	"io"
 	"math/big"
 	"os"
+	"strconv"
 )

 // defaultCount is how many numbers gofib prints when -n is omitted.
@@ -33,19 +34,33 @@ func Fib(n int) *big.Int {
 }

 // run writes the first count Fibonacci numbers to w. In text mode each
-// line is "<index>: <value>"; in JSON mode each line is one JSON object
-// {"index": <int>, "fib": "<value>"} (JSON Lines). It returns an error
-// when count < 1.
-func run(w io.Writer, count int, asJSON bool) error {
+// line is "<index>: <value>"; with pretty the index and value columns
+// are right-aligned, each padded to the width of the largest index and
+// value among the printed numbers, separated by ": ". In JSON mode each
+// line is one JSON object {"index": <int>, "fib": "<value>"} (JSON
+// Lines); pretty has no effect there. It returns an error when
+// count < 1.
+func run(w io.Writer, count int, asJSON, pretty bool) error {
 	if count < 1 {
 		return fmt.Errorf("invalid value %d for flag -n: must be >= 1", count)
 	}
 	enc := json.NewEncoder(w)
+	// Pretty text mode aligns both columns; the widths come from the
+	// largest line printed, i.e. the count-th number.
+	idxW, valW := 0, 0
+	if pretty && !asJSON {
+		idxW = len(strconv.Itoa(count))
+		valW = len(Fib(count).String())
+	}
 	for i := 1; i <= count; i++ {
 		if asJSON {
 			if err := enc.Encode(fibLine{Index: i, Fib: Fib(i).String()}); err != nil {
 				return err
 			}
+			continue
+		}
+		if pretty {
+			fmt.Fprintf(w, "%*d: %*s\n", idxW, i, valW, Fib(i).String())
 		} else {
 			fmt.Fprintf(w, "%d: %v\n", i, Fib(i))
 		}
@@ -56,8 +71,9 @@ func run(w io.Writer, count int, asJSON bool) error {
 func main() {
 	n := flag.Int("n", defaultCount, "how many Fibonacci numbers to print (must be >= 1; default 100)")
 	asJSON := flag.Bool("json", false, "emit JSON Lines instead of text: one {\"index\": i, \"fib\": \"value\"} object per number")
+	pretty := flag.Bool("pretty", false, "align text output in two right-aligned columns, padded to the largest index and value (only affects text mode; ignored with -json)")
 	flag.Parse()
-	if err := run(os.Stdout, *n, *asJSON); err != nil {
+	if err := run(os.Stdout, *n, *asJSON, *pretty); err != nil {
 		fmt.Fprintln(os.Stderr, err)
 		os.Exit(1)
 	}

